import{_ as e,c as o,o as d,ae as l}from"./chunks/framework.CDjunVez.js";const h=JSON.parse('{"title":"为生成器做好准备","description":"","frontmatter":{},"headers":[],"relativePath":"zh/manual/generator_preparation.md","filePath":"zh/manual/generator_preparation.md"}'),a={name:"zh/manual/generator_preparation.md"};function n(c,t,s,i,r,g){return d(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="为生成器做好准备" tabindex="-1">为生成器做好准备 <a class="header-anchor" href="#为生成器做好准备" aria-label="Permalink to &quot;为生成器做好准备&quot;">​</a></h1><p>扩展音符盒（Extended Note Block）拥有许多自定义 NBT 标签，利用这些标签可以实现比传统音符盒更丰富的音乐效果。这对于通过命令方块或外部生成器批量生成音符盒非常有用。</p><h2 id="nbt-结构概览" tabindex="-1">NBT 结构概览 <a class="header-anchor" href="#nbt-结构概览" aria-label="Permalink to &quot;NBT 结构概览&quot;">​</a></h2><p>扩展音符盒的 NBT 数据主要分为<strong>基础属性</strong>和<strong>高级数据 (AdvancedData)</strong> 两部分。</p><h3 id="基础属性-root" tabindex="-1">基础属性 (Root) <a class="header-anchor" href="#基础属性-root" aria-label="Permalink to &quot;基础属性 (Root)&quot;">​</a></h3><p>这些属性直接位于 NBT 的根节点下：</p><table tabindex="0"><thead><tr><th style="text-align:left;">标签名</th><th style="text-align:left;">类型</th><th style="text-align:left;">描述</th><th style="text-align:left;">范围/单位</th><th style="text-align:left;">默认值</th></tr></thead><tbody><tr><td style="text-align:left;"><code>note</code></td><td style="text-align:left;">Int</td><td style="text-align:left;">MIDI 音高</td><td style="text-align:left;">0-127 (60 为中央C)</td><td style="text-align:left;">60</td></tr><tr><td style="text-align:left;"><code>velocity</code></td><td style="text-align:left;">Int</td><td style="text-align:left;">MIDI 力度 (基础音量)</td><td style="text-align:left;">0-127</td><td style="text-align:left;">100</td></tr><tr><td style="text-align:left;"><code>sustainTime</code></td><td style="text-align:left;">Int</td><td style="text-align:left;">音符持续时间</td><td style="text-align:left;">游戏刻 (Ticks, 20 ticks = 1s)</td><td style="text-align:left;">40</td></tr><tr><td style="text-align:left;"><code>delayedPlayingTime</code></td><td style="text-align:left;">Int</td><td style="text-align:left;">延迟播放时间</td><td style="text-align:left;">毫秒 (ms)</td><td style="text-align:left;">0</td></tr><tr><td style="text-align:left;"><code>fadeInTime</code></td><td style="text-align:left;">Int</td><td style="text-align:left;">淡入时间</td><td style="text-align:left;">游戏刻 (Ticks)</td><td style="text-align:left;">0</td></tr><tr><td style="text-align:left;"><code>fadeOutTime</code></td><td style="text-align:left;">Int</td><td style="text-align:left;">淡出时间</td><td style="text-align:left;">游戏刻 (Ticks)</td><td style="text-align:left;">0</td></tr></tbody></table><h3 id="方块状态-block-states" tabindex="-1">方块状态 (Block States) <a class="header-anchor" href="#方块状态-block-states" aria-label="Permalink to &quot;方块状态 (Block States)&quot;">​</a></h3><p>除了 NBT 数据，扩展音符盒还使用 BlockStates 来处理红石信号和视觉表现。</p><table tabindex="0"><thead><tr><th style="text-align:left;">状态名</th><th style="text-align:left;">类型</th><th style="text-align:left;">可选值</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>pitch</code></td><td style="text-align:left;">Enum</td><td style="text-align:left;"><code>c</code>, <code>cs</code>, <code>d</code>, <code>ds</code>, <code>e</code>, <code>f</code>, <code>fs</code>, <code>g</code>, <code>gs</code>, <code>a</code>, <code>as</code>, <code>b</code></td><td style="text-align:left;">对应当前音符在一个八度内的音高（Note % 12）。主要用于资源包更改方块纹理。例如 <code>cs</code> 代表 C#。</td></tr><tr><td style="text-align:left;"><code>powered</code></td><td style="text-align:left;">Boolean</td><td style="text-align:left;"><code>true</code>, <code>false</code></td><td style="text-align:left;">标记方块是否被红石信号激活。用于检测信号边缘（上升沿/下降沿）。</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">注意</p><p>当你使用 <code>setblock</code> 放置方块时，通常不需要手动指定 <code>pitch</code>，因为方块在被红石激活时，会根据 NBT 中的 <code>note</code> 值自动计算并更新这个状态。</p></div><h3 id="高级数据-advanceddata-compound" tabindex="-1">高级数据 (<code>AdvancedData</code> Compound) <a class="header-anchor" href="#高级数据-advanceddata-compound" aria-label="Permalink to &quot;高级数据 (`AdvancedData` Compound)&quot;">​</a></h3><p>所有高级功能的数据都存储在一个名为 <code>AdvancedData</code> 的复合标签内。生成器需要构造精确的 List 数据结构。</p><h4 id="_1-弯音曲线-pitchbendpoints" tabindex="-1">1. 弯音曲线 (<code>PitchBendPoints</code>) <a class="header-anchor" href="#_1-弯音曲线-pitchbendpoints" aria-label="Permalink to &quot;1. 弯音曲线 (`PitchBendPoints`)&quot;">​</a></h4><ul><li><strong>类型</strong>: <code>List&lt;Compound&gt;</code></li><li><strong>元素结构</strong>: <code>{t: &lt;float&gt;, v: &lt;float&gt;}</code><ul><li><code>t</code> (Time): 时间点，范围 <code>0.0</code> (开始) 到 <code>1.0</code> (结束)。</li><li><code>v</code> (Value): <strong>半音 (Semitones)</strong> 偏移量。 <ul><li><code>0.0</code>: 无偏移（原音高）。</li><li><code>12.0</code>: 升高一个八度。</li><li><code>-12.0</code>: 降低一个八度。</li><li>支持小数，例如 <code>0.5</code> 半音（50 音分）。</li></ul></li></ul></li><li><strong>插值行为</strong>: 游戏会在两个关键点之间进行<strong>线性插值</strong>。</li></ul><h4 id="_2-音量包络-volumepoints" tabindex="-1">2. 音量包络 (<code>VolumePoints</code>) <a class="header-anchor" href="#_2-音量包络-volumepoints" aria-label="Permalink to &quot;2. 音量包络 (`VolumePoints`)&quot;">​</a></h4><ul><li><strong>类型</strong>: <code>List&lt;Compound&gt;</code></li><li><strong>元素结构</strong>: <code>{t: &lt;float&gt;, v: &lt;float&gt;}</code><ul><li><code>t</code> (Time): 时间点，范围 <code>0.0</code> 到 <code>1.0</code>。</li><li><code>v</code> (Value): <strong>音量倍率 (Multiplier)</strong>。 <ul><li><code>1.0</code>: 标准音量（由 <code>velocity</code> 决定）。</li><li><code>0.0</code>: 静音。</li><li><code>2.0</code>: 两倍标准音量。</li></ul></li></ul></li><li><strong>插值行为</strong>: 游戏会在两个关键点之间进行<strong>线性插值</strong>。</li><li><strong>覆盖规则</strong>: 一旦此列表非空，NBT 根节点的 <code>fadeInTime</code>/<code>fadeOutTime</code> 将失效。</li></ul><h4 id="_3-声源移动路径-soundpath" tabindex="-1">3. 声源移动路径 (<code>SoundPath</code>) <a class="header-anchor" href="#_3-声源移动路径-soundpath" aria-label="Permalink to &quot;3. 声源移动路径 (`SoundPath`)&quot;">​</a></h4><ul><li><strong>类型</strong>: <code>List&lt;Compound&gt;</code></li><li><strong>元素结构</strong>: <code>{x: &lt;double&gt;, y: &lt;double&gt;, z: &lt;double&gt;}</code><ul><li>这组坐标是<strong>相对于音符盒中心的偏移量</strong>。例如 <code>{x:0, y:1, z:0}</code> 表示在音符盒上方 1 格处。</li></ul></li><li><strong>采样行为</strong>: 与曲线不同，<code>SoundPath</code> <strong>不进行线性插值</strong>。 <ul><li>游戏会根据当前播放进度，计算出索引 <code>Index = Progress * (Size - 1)</code>，直接取对应点的位置。</li><li><strong>建议</strong>: 如果需要平滑移动，生成器应生成足够密集的点（例如，如果 <code>sustainTime</code> 为 40 ticks，建议生成 40 个路径点，每 tick 一个点）。</li></ul></li></ul><h4 id="_4-gui-表达式缓存-expressionx-y-z" tabindex="-1">4. GUI 表达式缓存 (<code>ExpressionX</code>/<code>Y</code>/<code>Z</code>) <a class="header-anchor" href="#_4-gui-表达式缓存-expressionx-y-z" aria-label="Permalink to &quot;4. GUI 表达式缓存 (`ExpressionX`/`Y`/`Z`)&quot;">​</a></h4><ul><li><strong>类型</strong>: <code>String</code></li><li>这些仅字符串用于在 GUI 中回显用户输入的公式（如 <code>sin(t * pi)</code>）。</li></ul><div class="warning custom-block"><p class="custom-block-title">重要</p><p>游戏核心逻辑<strong>完全忽略</strong>这些字符串。如果你是一个外部生成器，<strong>不需要</strong>生成这些字符串，除非你想让玩家打开 GUI 时看到特定的公式。你需要生成的是上方的 <code>SoundPath</code> 列表。</p></div><h2 id="setblock-命令示例" tabindex="-1">Setblock 命令示例 <a class="header-anchor" href="#setblock-命令示例" aria-label="Permalink to &quot;Setblock 命令示例&quot;">​</a></h2><p>你可以使用 <code>/setblock</code> 命令来放置一个带有预设 NBT 数据的扩展音符盒。</p><p><strong>基础示例：</strong></p><div class="language-mcfunction vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mcfunction</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>setblock ~ ~1 ~ extendednoteblock:extended_note_block{note:64, velocity:120, sustainTime:10}</span></span></code></pre></div><p><strong>高级示例（包含弯音）：</strong></p><div class="language-mcfunction vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mcfunction</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>setblock ~ ~1 ~ extendednoteblock:extended_note_block{note:60, sustainTime:40, AdvancedData:{PitchBendPoints:[{t:0.0f, v:0.0f}, {t:1.0f, v:12.0f}]}}</span></span></code></pre></div><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">SoundPath 与 Expression 的关系</p><p>在 <code>AdvancedData</code> 中，你可能会发现同时存在 <code>SoundPath</code> 和 <code>ExpressionX/Y/Z</code>。</p><ul><li><strong>Expr (表达式)</strong>：仅用于<strong>GUI 界面显示和编辑</strong>。游戏在运行时<strong>不会</strong>计算这些表达式。</li><li><strong>SoundPath (路径)</strong>：这是游戏实际播放声音时使用的路径数据。</li></ul><p><strong>关键点：</strong> 如果你编写生成器，<strong>必须直接生成 <code>SoundPath</code> 列表数据</strong>。仅仅写入 <code>Expression</code> 字符串是无效的，声音不会移动，除非玩家手动打开 GUI 并保存，此时客户端才会根据表达式计算出路径点并写入 <code>SoundPath</code>。</p></div><div class="info custom-block"><p class="custom-block-title">音量控制优先权</p><p>音量主要由以下两个属性控制：</p><ol><li><strong><code>velocity</code> (基础力度)</strong>：决定全曲的基础音量。</li><li><strong><code>VolumePoints</code> (高级音量曲线)</strong>：如果 <code>AdvancedData</code> 中存在非空的 <code>VolumePoints</code> 列表，它将<strong>完全覆盖 (Override)</strong> 基础 <code>velocity</code> 的效果。</li></ol><p>这意味着，如果你想使用动态的音量包络（ADSR等），应使用 <code>VolumePoints</code>；如果是简单的固定音量，使用 <code>velocity</code> 即可。</p></div>',31)])])}const p=e(a,[["render",n]]);export{h as __pageData,p as default};
